  'statistical': { role: 'predict', name: 'Statistical context models', note: 'Estimate P(next symbol | context). Slow, but the ratio ceiling of lossless coding.' },
  // quantize
  'scalar':      { role: 'quantize', name: 'Scalar quantizers', note: 'One number at a time onto a grid.' },
  'vector':      { role: 'quantize', name: 'Vector quantizers', note: 'A whole vector at a time onto a trained codebook.' },
  'blockint':    { role: 'quantize', name: 'Block integer quantizers', note: 'Low-bit integers plus a scale per small block. Built for GPUs.' },
  // entropy
  'prefix':      { role: 'entropy', name: 'Prefix codes', note: 'One integer number of bits per symbol. Fast, but can waste up to 1 bit/symbol.' },
  'arith':       { role: 'entropy', name: 'Arithmetic-style coders', note: 'Fractional bits per symbol. Reach the entropy bound.' },
  'special':     { role: 'entropy', name: 'Special-purpose codes', note: 'Shaped for one distribution: geometric values, runs of zeros.' },
  'selection':   { role: 'quantize', name: 'Token selection / eviction', note: 'A two-level quantizer: all bits or zero bits, chosen per token.' },
