  'adversarial': { role: 'perceptual', name: 'Learned perceptual losses', note: 'A second network that judges what looks or sounds real.' },
  'attention':   { role: 'perceptual', name: 'Machine-reader importance', note: 'The consumer is a softmax: which tokens and coordinates the downstream model is sensitive to.' },
  // prior
  'tables':      { role: 'prior', name: 'Standard tables', note: 'Constants baked into the format spec.' },
  'trained':     { role: 'prior', name: 'Trained side information', note: 'Fitted to one kind of data, shipped out-of-band.' },
  'weights':     { role: 'prior', name: 'Learned decoders', note: 'The decoder itself is a trained model.' },
  'tiered':      { role: 'prior', name: 'Tiered copies', note: 'A lossless original one hop away, not counted in the fast memory. Out-of-band in space rather than in time.' },
